CAT = "cpatcpScorp"; SEG = "SCO"
Q = [
("Dee transfers property with a basis of $30,000 and a value of $80,000, subject to a $45,000 mortgage, to her S corporation for stock, and she has 100% control. Her stock basis afterwards is:",
 "$0", ["$15,000", "$35,000", "$30,000"],
 "She recognizes $15,000 of gain because the debt exceeds her basis (section 357(c)). Stock basis is $30,000 - $45,000 + $15,000 = $0.", 0),
("An S corporation shareholder personally guarantees a $50,000 bank loan to the corporation. The guarantee gives her debt basis of:",
 "$0 until she pays the bank", ["$50,000 at once", "$25,000 at once", "$50,000 if she owns 50%"],
 "Debt basis comes only from bona fide loans the shareholder makes directly to the corporation (Reg. 1.1366-2). A guarantee counts only once she actually pays on it."),
("An S shareholder with $5,000 of stock basis lends the corporation $20,000. Her share of this year's loss is $18,000, all deductible. Her debt basis at year end is:",
 "$7,000", ["$20,000", "$2,000", "$13,000"],
 "The loss reduces stock basis to zero first, using $5,000, then debt basis by the other $13,000: $20,000 - $13,000 = $7,000.", 7000),
("An S shareholder's basis in a $20,000 written note from the corporation, held for years, has been reduced to $7,000 by losses. In a later year with no income to restore basis, the corporation repays the note in full. She recognizes:",
 "$13,000 of capital gain", ["$13,000 of ordinary income", "$20,000 of capital gain", "No gain at all"],
 "Repayment of reduced-basis debt is gain: $20,000 - $7,000. On a note held as a capital asset it is capital gain; an open-account advance would give ordinary income."),
("An S corporation distributes land with a basis of $10,000 and a value of $25,000 to its sole shareholder, whose stock basis was $40,000 before the distribution. Her stock basis afterwards is:",
 "$30,000", ["$15,000", "$45,000", "$40,000"],
 "The corporation's $15,000 gain passes through and raises her basis to $55,000, then the distribution reduces it by the land's $25,000 value.", 30000),
("An S corporation distributes property with a basis of $30,000 and a value of $18,000 to a shareholder as a nonliquidating distribution. The $12,000 decline in value is:",
 "Never deducted by anyone", ["Passed through as a loss", "Added to her stock basis", "Carried forward by the S corp"],
 "Section 311(a) denies the corporation a loss, so nothing passes through, and the shareholder takes a $18,000 basis. Selling first and distributing cash would save the loss."),
("An S corporation that was never a C corporation liquidates, distributing land with a basis of $20,000 and a value of $90,000 to its sole shareholder, whose stock basis was $50,000. On the liquidation itself, after the pass-through gain, she recognizes:",
 "A $30,000 capital loss", ["A $40,000 capital gain", "A $70,000 capital gain", "No gain or loss"],
 "The $70,000 corporate gain passes through and raises her basis to $120,000. She then receives land worth $90,000 for stock with a $120,000 basis, a $30,000 loss. Overall she nets $40,000 of gain."),
("A shareholder owning 50% of a calendar-year S corporation sells all her shares on day 146 of a 365-day year. Income for the year is $73,000, and no election to close the books is made. Income allocated to her is:",
 "$14,600", ["$36,500", "$14,500", "$21,900"],
 "Income is allocated per share, per day, and the seller counts as owner on the day of sale: $73,000 / 365 x 146 x 50% = $14,600.", 14600),
("To allocate S corporation income by closing the books on the date a shareholder sells all her shares, the election requires agreement of:",
 "The corporation and affected owners", ["All shareholders on that day", "Only the selling shareholder", "Only the IRS"],
 "Section 1377(a)(2) needs the corporation and all affected shareholders, meaning the seller and those she transferred shares to."),
("After an S election terminates, the corporation generally cannot elect S status again, without IRS consent, for:",
 "5 tax years", ["2 tax years", "3 tax years", "10 tax years"],
 "Section 1362(g) bars a new election before the fifth tax year beginning after the first year the termination is effective, unless the IRS consents."),
("When an S election terminates partway through a calendar year, the corporation's year is:",
 "Split into S and C short years", ["Treated as an S year in full", "Treated as a C year in full", "Extended to a 15-month year"],
 "Section 1362(e) creates an S short year ending the day before termination and a C short year for the rest, with income allocated by days unless the corporation elects otherwise."),
("Cash distributions made after an S election ends, during the post-termination transition period, come first from:",
 "The accumulated adjustments account", ["Accumulated C corporation E&P", "Stock basis without limit", "Current-year E&P"],
 "Under section 1371(e) cash distributions in that period reduce basis to the extent of AAA, so shareholders can take out previously taxed S income tax-free."),
("An S corporation with both AAA and accumulated C corporation E&P may elect to treat distributions as coming first from the E&P, mainly to:",
 "Purge E&P that risks termination", ["Make the distributions tax-free", "Raise shareholder stock basis", "Avoid the built-in gains tax"],
 "The section 1368(e)(3) election, with consent of affected shareholders, makes distributions taxable dividends but clears E&P, ending the passive income tax and termination risk."),
("A C corporation elected S status on January 1, 2024, when an asset had a value of $300,000 and a basis of $180,000. In 2026 it sells the asset for $340,000. With ample taxable income, the built-in gains tax is:",
 "$25,200", ["$33,600", "$8,400", "$0"],
 "Recognized built-in gain is capped at the $120,000 built in at conversion; the $40,000 of later growth is not built-in gain. $120,000 x 21% = $25,200.", 25200),
("An S corporation's net recognized built-in gain for a year is limited to:",
 "Its taxable income as if a C corp", ["Shareholders' total stock basis", "Its accumulated E&P", "Half of the gain realized"],
 "Section 1374(d)(2) caps the gain taxed at the corporation's taxable income computed as a C corporation; any excess carries to later years in the recognition period."),
("Ken owns 50% of an S corporation and transfers equipment with a basis of $12,000 and a value of $20,000 for more stock, ending with 60%. No one else transfers property. The corporation's basis in the equipment is:",
 "$20,000", ["$12,000", "$8,000", "$16,000"],
 "Ken lacks 80% control after the exchange, so section 351 does not apply. He recognizes $8,000 of gain, and the corporation takes a cost basis equal to the value.", 20000),
]
